bounded_host_request.command:
set -euo pipefail
src=cba26174b30e30e408cc045859a132de23f68e59
name=gace-createvdobot-videobot-poll-1
if test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true &&
 docker logs --tail 150 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$';then
 echo STK04_EXISTING_DM_READY=PASS
 exit 0
fi
git fetch --no-tags origin feat/assistant-ai-and-sales-core >/dev/null 2>&1 || { echo STK04_FETCH_FAILED; exit 61; }
git cat-file -e "$src^{commit}" || { echo STK04_SOURCE_NOT_AVAILABLE; exit 62; }
target="$HOME/.local/share/gace-create-videobot/sticker-poll-$src"
mkdir -p "$target"
chmod 700 "$target"
git archive "$src" | tar -xf - -C "$target" || { echo STK04_STAGE_FAILED; exit 63; }
grep -Fq "setDefaultAutoSelectFamily(false);" "$target/src/runtime/creatorPollingMain.mjs" || { echo STK04_IPV4_PATCH_ABSENT; exit 64; }
grep -Fq 'COPY --chown=node:node src ./src' "$target/deploy/Dockerfile" || { echo STK04_DOCKERFILE_NOT_FIXED; exit 65; }
image=create-videobot:sticker-poll-cba2617
log="$(mktemp /tmp/stk04-build.XXXXXXXX)"
trap 'rm -f "$log"' EXIT
if ! docker build --no-cache --pull=false --network host -f "$target/deploy/Dockerfile" -t "$image" "$target" >"$log" 2>&1;then
 echo STK04_IMAGE_BUILD_FAILED
 grep -Ei 'failed|error|timeout|unavailable' "$log" | tail -n 4 | sed -E 's#https?://[^ ]+#URL_REDACTED#g' || true
 exit 66
fi
docker run --rm --network none --pull never --entrypoint /bin/sh "$image" -c \
 'test -f /opt/videobot/src/runtime/main.mjs && test -f /opt/videobot/src/runtime/creatorPollingMain.mjs && test -d /opt/videobot/node_modules/pg' >/dev/null || { echo STK04_IMAGE_MISSING_MODULE; exit 67; }
docker run --rm --network none --pull never --entrypoint node "$image" --input-type=module \
 -e "import('./src/runtime/creatorPollingMain.mjs').then(()=>process.exit(0)).catch(()=>process.exit(1))" >/dev/null || { echo STK04_IMAGE_IMPORT_FAILED; exit 68; }
echo STK04_IMAGE_AND_IMPORT=PASS
test -n "$(docker inspect "$name" 2>/dev/null)" || { echo STK04_EXISTING_CONTAINER_ABSENT; exit 69; }
token="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_telegram_token"}}{{.Source}}{{end}}{{end}}' "$name")"
dbpass="$HOME/.local/state/create-videobot/secrets/gserver_postgres_password"
test -f "$token" && test -f "$dbpass" && test ! -L "$token" && test ! -L "$dbpass" || { echo STK04_EXISTING_SECRETS_UNAVAILABLE; exit 70; }
uid="$(docker run --rm --network none --pull never --entrypoint id "$image" -u)"
test "$(stat -c '%u' "$token")" = "$uid" && test "$(stat -c '%u' "$dbpass")" = "$uid" || { echo STK04_SECRET_OWNERS_INVALID; exit 71; }
test "$(stat -c '%a' "$token")" = 600 && test "$(stat -c '%a' "$dbpass")" = 600 || { echo STK04_SECRET_MODES_INVALID; exit 72; }
pg="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])postgres([-_]|$)' || true)"
test "$(printf '%s\n' "$pg" | sed '/^$/d' | wc -l)" -eq 1 || { echo STK04_POSTGRES_NOT_UNIQUE; exit 73; }
user="$(docker exec "$pg" sh -c 'printf %s "$POSTGRES_USER"')"
net="$(docker inspect -f '{{range $k,$v := .NetworkSettings.Networks}}{{println $k}}{{end}}' "$pg" | sed '/^$/d')"
test -n "$user" && test "$net" = deploy_default || { echo STK04_DB_OWNER_UNVERIFIED; exit 74; }
other="$(docker ps --format '{{.Names}}' | grep -Ei 'create-videobot|createvdobot|videobot-poll|videobot-telegram' | grep -Fxv "$name" || true)"
test -z "$other" || { echo STK04_DUPLICATE_CREATOR_CONSUMER; exit 75; }
export VIDEOBOT_TELEGRAM_TOKEN_SOURCE="$token" VIDEOBOT_DB_PASSWORD_SOURCE="$dbpass"
export GSERVER_POSTGRES_USER="$user" GSERVER_POSTGRES_NETWORK="$net"
docker compose -p gace-createvdobot -f "$target/deploy/compose.videobot.poll.yaml" config --quiet || { echo STK04_COMPOSE_CONFIG_INVALID; exit 76; }
docker image tag create-videobot:local-poll create-videobot:poll-rollback-cba2617
docker image tag "$image" create-videobot:local-poll
docker compose -p gace-createvdobot -f "$target/deploy/compose.videobot.poll.yaml" up -d --no-build --force-recreate videobot-poll >/dev/null 2>&1 || { echo STK04_RECREATE_FAILED; exit 77; }
sleep 12
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo STK04_POLL_NOT_RUNNING; exit 78; }
docker logs --tail 120 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$' || { echo STK04_POLL_READY_NOT_VERIFIED; exit 79; }
echo STK04_CREATEVDO_DM_POLL_READY=PASS
docker logs --tail 120 "$name" 2>&1 | grep -E '^CREATOR_(DM|GATE|POLL)_' | tail -n 8 || true
